from fractions import Fraction


def split_interleaved(seq):
    return list(seq[0::2]), list(seq[1::2])


def by_differences(seq):
    rows = [list(seq)]
    while len(rows[-1]) > 1 and len(set(rows[-1])) > 1:
        r = rows[-1]
        rows.append([b - a for a, b in zip(r, r[1:])])
    if len(rows[-1]) < 2:
        return None
    return sum(r[-1] for r in rows)


def by_ratio(seq):
    if len(seq) < 3 or 0 in seq[:-1]:
        return None
    ratios = {Fraction(b, a) for a, b in zip(seq, seq[1:])}
    return seq[-1] * ratios.pop() if len(ratios) == 1 else None


def simple(seq):
    v = by_differences(seq)
    return v if v is not None else by_ratio(seq)


def next_term(seq):
    v = simple(seq)
    if v is None:
        odd_places, even_places = split_interleaved(seq)
        a, b = simple(odd_places), simple(even_places)
        if a is None or b is None:
            return None
        v = a if len(seq) % 2 == 0 else b
    v = Fraction(v)
    return int(v) if v.denominator == 1 else v
